composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      KOMODO_DATABASE_ADDRESS: "{{serviceName}}-mongo:27017"
      KOMODO_DATABASE_USERNAME: komodo
      KOMODO_DATABASE_PASSWORD: {{env.MONGO_PASSWORD}}
      MONGO_PASSWORD: {{env.MONGO_PASSWORD}}
      KOMODO_PASSKEY: {{env.KOMODO_PASSKEY}}
    volumes:
      - {{appDataPath}}/repo-cache:/repo-cache
  {{serviceName}}-mongo:
    image: mongo:7
    container_name: {{serviceName}}-mongo
    restart: unless-stopped
    environment:
      MONGO_INITDB_ROOT_USERNAME: komodo
      MONGO_INITDB_ROOT_PASSWORD: {{env.MONGO_PASSWORD}}
